with ValidDepartments as (select * from departments where location = 'Chiang Mai' and budget < 3775000), budget_bucket_summary as (select case when budget >= 4424000 then 'high' when budget >= 819000 then 'mid' else 'low' end as budget_bucket, sum(budget) as total_budget from ValidDepartments group by case when budget >= 4424000 then 'high' when budget >= 819000 then 'mid' else 'low' end) select * from budget_bucket_summary where total_budget < 9033000 order by budget_bucket asc
